CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,"emailVerified" boolean NOT NULL,image text,"createdAt" timestamp NOT NULL,"updatedAt" timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY,"expiresAt" timestamp NOT NULL,token text NOT NULL UNIQUE,"ipAddress" text,"userAgent" text,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"createdAt" timestamp NOT NULL,"updatedAt" timestamp NOT NULL);
CREATE INDEX IF NOT EXISTS idx_session_user ON session("userId");
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamp,"refreshTokenExpiresAt" timestamp,scope text,password text,"createdAt" timestamp NOT NULL,"updatedAt" timestamp NOT NULL);
CREATE INDEX IF NOT EXISTS account_user ON account("userId");
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamp NOT NULL,"createdAt" timestamp NOT NULL,"updatedAt" timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS networks (id text PRIMARY KEY,name text NOT NULL);
CREATE TABLE IF NOT EXISTS franchisees (id text PRIMARY KEY,network_id text NOT NULL REFERENCES networks(id),name text NOT NULL,UNIQUE(network_id,id));
CREATE TABLE IF NOT EXISTS stores (id text PRIMARY KEY,network_id text NOT NULL REFERENCES networks(id),franchisee_id text NOT NULL,name text NOT NULL,UNIQUE(network_id,id),FOREIGN KEY(network_id,franchisee_id) REFERENCES franchisees(network_id,id));
CREATE TABLE IF NOT EXISTS memberships (user_id text PRIMARY KEY REFERENCES "user"(id),network_id text NOT NULL REFERENCES networks(id),role text NOT NULL CHECK(role IN ('admin','operator')),UNIQUE(network_id,user_id));
CREATE TABLE IF NOT EXISTS store_access (network_id text NOT NULL,user_id text NOT NULL,store_id text NOT NULL,PRIMARY KEY(user_id,store_id),FOREIGN KEY(network_id,user_id) REFERENCES memberships(network_id,user_id),FOREIGN KEY(network_id,store_id) REFERENCES stores(network_id,id));
CREATE TABLE IF NOT EXISTS products (id serial PRIMARY KEY,network_id text NOT NULL REFERENCES networks(id),name text NOT NULL,code text NOT NULL,UNIQUE(network_id,code),UNIQUE(network_id,id));
CREATE TABLE IF NOT EXISTS listings (network_id text NOT NULL,store_id text NOT NULL,product_id integer NOT NULL,price integer NOT NULL CHECK(price BETWEEN 0 AND 99999999),stock integer NOT NULL DEFAULT 0 CHECK(stock BETWEEN 0 AND 999999),minimum integer NOT NULL CHECK(minimum BETWEEN 0 AND 999999),version integer NOT NULL DEFAULT 0,PRIMARY KEY(store_id,product_id),FOREIGN KEY(network_id,store_id) REFERENCES stores(network_id,id),FOREIGN KEY(network_id,product_id) REFERENCES products(network_id,id));
CREATE TABLE IF NOT EXISTS movements (id text NOT NULL,network_id text NOT NULL,store_id text NOT NULL,product_id integer NOT NULL,actor_id text NOT NULL REFERENCES "user"(id),before_stock integer NOT NULL,after_stock integer NOT NULL,reason text NOT NULL,at timestamptz NOT NULL DEFAULT now(),request_json text NOT NULL,PRIMARY KEY(network_id,id),FOREIGN KEY(store_id,product_id) REFERENCES listings(store_id,product_id),FOREIGN KEY(network_id,store_id) REFERENCES stores(network_id,id));
CREATE INDEX IF NOT EXISTS movement_store ON movements(network_id,store_id,at DESC);

